data = transpose(recs)
maxYear = [].concat(meta.maxYear)[0]
minYear = [].concat(meta.minYear)[0]
lastUpdated = [].concat(meta.lastUpdated)[0]
forms = [].concat(meta.forms)
components = [].concat(meta.components)
hazards = [].concat(meta.hazards)
hazardColors = ["#2a78d6", "#eb6834", "#1baf7a", "#6250d6"]
fmtN = d3.format(",")


































































Filters

viewof countries = Inputs.checkbox(["United States", "Canada"], {label: "Country", value: ["United States", "Canada"]})
viewof yearFrom = Inputs.range([minYear, maxYear], {step: 1, value: minYear, label: "From"})
viewof yearTo = Inputs.range([minYear, maxYear], {step: 1, value: maxYear, label: "To"})
viewof form = Inputs.select(["All", ...forms], {label: "What was recalled"})
viewof component = Inputs.select(["All", ...components], {label: "Failed part"})
viewof hazard = Inputs.select(["All", ...hazards], {label: "Hazard"})
viewof ebikeOnly = Inputs.toggle({label: "E-bike related only", value: false})
viewof includeProbable = Inputs.toggle({label: "Include probable cases", value: true})
viewof measure = Inputs.radio(["Recall events", "Units recalled"], {label: "Count", value: "Recall events"})
viewof view = Inputs.radio(["By hazard", "By failed part"], {label: "Chart", value: "By hazard"})












































































lo = Math.min(yearFrom, yearTo)
hi = Math.max(yearFrom, yearTo)

// Rows passing every filter, then one row per recall event
filtered = {
  const rows = data.filter(d =&gt;
    countries.includes(d.country) &&
    d.recall_year &gt;= lo && d.recall_year &lt;= hi &&
    (form === "All" || d.product_form === form) &&
    (component === "All" || d.failed_component === component) &&
    (hazard === "All" || d.hazard_group === hazard) &&
    (!ebikeOnly || d.is_ebike_related) &&
    (includeProbable || d.case_status === "confirmed"));
  const seen = new Set();
  return rows.filter(d =&gt; {
    if (seen.has(d.event_id)) return false;
    seen.add(d.event_id);
    return true;
  });
}

w = d =&gt; measure === "Recall events" ? 1 : (d.units_recalled ?? 0)
measureLabel = measure === "Recall events" ? "recall events" : "units recalled"
years = d3.range(lo, hi + 1)












































tiles = {
  const n = filtered.length;
  const fall = n ? filtered.filter(d =&gt; d.hazard_group === "Fall or crash").length / n : 0;
  const ranked = d3.rollups(filtered.filter(d =&gt; d.failed_component !== "Other or unclear"),
                            v =&gt; v.length, d =&gt; d.failed_component)
                   .sort((a, b) =&gt; b[1] - a[1]);
  const top = ranked.length ? ranked[0] : ["None", 0];
  const eb = n ? filtered.filter(d =&gt; d.is_ebike_related).length / n : 0;
  const units = d3.sum(filtered, d =&gt; d.units_recalled ?? 0);
  const pct = x =&gt; `${Math.round(100 * x)}%`;
  return html`&lt;div class="stat-row dash-tiles"&gt;
    &lt;div class="stat-box"&gt;&lt;span class="num"&gt;${fmtN(n)}&lt;/span&gt;&lt;span class="lab"&gt;recall events (${fmtN(units)} units)&lt;/span&gt;&lt;/div&gt;
    &lt;div class="stat-box"&gt;&lt;span class="num"&gt;${pct(fall)}&lt;/span&gt;&lt;span class="lab"&gt;fall or crash hazard&lt;/span&gt;&lt;/div&gt;
    &lt;div class="stat-box"&gt;&lt;span class="num"&gt;${n ? pct(top[1] / n) : "0%"}&lt;/span&gt;&lt;span class="lab"&gt;top failed part: ${top[0].toLowerCase()}&lt;/span&gt;&lt;/div&gt;
    &lt;div class="stat-box"&gt;&lt;span class="num"&gt;${pct(eb)}&lt;/span&gt;&lt;span class="lab"&gt;e-bike related&lt;/span&gt;&lt;/div&gt;
  &lt;/div&gt;`;
}







totals = years.map(y =&gt; ({year: y, total: d3.sum(filtered.filter(d =&gt; d.recall_year === y), w)}))

// Three-year trailing average, leaving out the current (partial) year
rolling = totals
  .filter(t =&gt; t.year &lt; maxYear)
  .map((t, i, arr) =&gt; i &lt; 2 ? null : {year: t.year, avg: d3.mean(arr.slice(i - 2, i + 1), d =&gt; d.total)})
  .filter(Boolean)

byHazard = years.flatMap(y =&gt; hazards.map(h =&gt; ({
  year: y,
  hazard: h,
  value: d3.sum(filtered.filter(d =&gt; d.recall_year === y && d.hazard_group === h), w)
})))

byPart = components.flatMap(c =&gt; years.map(y =&gt; ({
  component: c,
  year: y,
  value: d3.sum(filtered.filter(d =&gt; d.recall_year === y && d.failed_component === c), w)
})))






























html`&lt;div class="dash-chart-title"&gt;${view === "By hazard"
  ? `${measure} per year, by hazard`
  : `${measure} per year, by failed part (same scale in every panel)`}&lt;/div&gt;`







{
  if (view === "By hazard") {
    const fig = Plot.plot({
      width,
      height: 380,
      marginLeft: 56,
      marginTop: 20,
      x: {label: null, tickFormat: "d", domain: [lo, hi + 1]},
      y: {label: measure === "Recall events" ? "Recall events per year" : "Units recalled per year", grid: true, tickFormat: "~s"},
      color: {domain: hazards, range: hazardColors, legend: true},
      marks: [
        Plot.rectY(byHazard, {
          x: "year", interval: 1, y: "value", fill: "hazard",
          fillOpacity: d =&gt; d.year === maxYear ? 0.45 : 1,
          insetLeft: 1, insetRight: 1,
          tip: true,
          title: d =&gt; `${d.year}${d.year === maxYear ? " (partial year)" : ""}\n${d.hazard}: ${fmtN(Math.round(d.value))} ${measureLabel}`
        }),
        Plot.lineY(rolling, {x: d =&gt; d.year + 0.5, y: "avg", stroke: "#0b2233", strokeWidth: 2, curve: "monotone-x"}),
        Plot.ruleY([0])
      ]
    });
    const wrap = html`&lt;div class="dash-chart"&gt;&lt;/div&gt;`;
    wrap.append(fig);
    return wrap;
  }
  const maxV = d3.max(byPart, d =&gt; d.value) || 1;
  const grid = html`&lt;div class="small-multiples"&gt;&lt;/div&gt;`;
  for (const c of components) {
    const rows = byPart.filter(d =&gt; d.component === c);
    const total = d3.sum(rows, d =&gt; d.value);
    const p = Plot.plot({
      width: 300, height: 130, marginLeft: 40, marginTop: 8,
      x: {domain: [lo, hi + 1], tickFormat: "d", ticks: 4, label: null},
      y: {domain: [0, maxV], ticks: 3, label: null, grid: true, tickFormat: "~s"},
      marks: [
        Plot.rectY(rows, {
          x: "year", interval: 1, y: "value", fill: "#1f4e79",
          fillOpacity: d =&gt; d.year === maxYear ? 0.45 : 1,
          insetLeft: 0.5, insetRight: 0.5,
          tip: true,
          title: d =&gt; `${c}, ${d.year}: ${fmtN(Math.round(d.value))} ${measureLabel}`
        }),
        Plot.ruleY([0])
      ]
    });
    const panel = html`&lt;div class="sm-panel"&gt;&lt;div class="sm-title"&gt;${c} &lt;span class="sm-total"&gt;${fmtN(Math.round(total))}&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;`;
    panel.append(p);
    grid.append(panel);
  }
  return grid;
}







html`&lt;p class="dash-note"&gt;${view === "By hazard"
  ? "Bars show each year's total, split by hazard. The dark line is the three-year average. "
  : ""}${maxYear} is a partial year (data to ${lastUpdated}), shown paler. Canadian notices start in 2008, so totals before then are US only. Joint US and Canadian recalls count once.${measure === "Units recalled"
  ? " Units are as stated in each notice: US notices usually count US units, and Canadian notices count units sold in Canada."
  : ""}&lt;/p&gt;`







DOM.download(() =&gt; new Blob([d3.csvFormat(filtered)], {type: "text/csv"}), "bike_recalls_filtered.csv", `Download these ${fmtN(filtered.length)} recalls (CSV)`)
